import React, { useEffect, useState } from "react";
import axios from "axios";

const RegisteredSellerLayer = () => {
  const [sellers, setSellers] = useState([]);
  const [loading, setLoading] = useState(false);

  const fetchRegisteredSellers = async () => {
    setLoading(true);
    try {
      const response = await axios.get(`${process.env.REACT_APP_BACKEND_URL}/api/sellers/registeredSellers`);
      setSellers(response.data);
      console.log("Registered sellers fetched successfully:", response.data);
    } catch (error) {
      console.error("Error fetching registered sellers:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRegisteredSellers();
  }, []);
const [showViewModal, setShowViewModal] = useState(false);
  const [selectedSeller, setSelectedSeller] = useState(null);
 

  return (
    <div className="dashboard-body__content">
      <div className="card common-card border border-gray-five">
        <div className="card-body">
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" }}>
            <h4 style={{ margin: 0 }}>Registered Sellers</h4>
          </div>
          {loading ? (
            <p>Loading sellers...</p>
          ) : (
            <div className="table-responsive" style={{ marginTop: "-20px" }}>
              <table className="table text-body">
                <thead>
                  <tr>
                    <th>SN.</th>
                    <th>Seller Name</th>
                    <th>Email</th>
                    <th>Phone</th>
                    <th className="text-center">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {sellers && sellers.length > 0 ? (
                    sellers.map((seller, index) => (
                      <tr key={seller._id || index}>
                        <td>{index + 1}</td>
                        <td>{seller?.basicInformation?.shopName}</td>
                        <td>{seller?.contactInformation?.emailAddress}</td>
                        <td>{seller?.contactInformation?.Mobileprimary}</td>
                        {/* <td className="text-center">
                          <div style={{ display: "flex", justifyContent: "center", gap: "10px" }}>
                            <button className="btn btn-primary text-white" style={{ backgroundColor: "blue", border: "none", padding: "6px 16px", borderRadius: "8px", fontWeight: "500" }}>View</button>
                            <button className="btn btn-success text-white" style={{ backgroundColor: "#198754", border: "none", padding: "6px 16px", borderRadius: "8px", fontWeight: "500" }}>Reset</button>
                            <button className="btn btn-danger text-white" style={{ backgroundColor: "red", border: "none", padding: "6px 16px", borderRadius: "8px", fontWeight: "500" }}>Delete</button>
                          </div>
                        </td> */}
                         <td>
                        <div className="d-flex gap-2 mt-2 justify-content-center">
                          {/* View button - Always visible */}
                          <button
                            className="btn btn-sm btn-info"
                            onClick={() => {
                              setSelectedSeller(seller);
                              setShowViewModal(true);
                            }}
                            style={{ backgroundColor: "blue" }}
                          >
                            View
                          </button>
                            {/* <button
                                className="btn btn-sm btn-danger"
                                style={{ backgroundColor: "red" }}
                              >
                                Delete
                              </button> */}

                        </div>
                      </td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan="5" className="text-center">No registered sellers found.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          )}

             {showViewModal && selectedSeller && (
          <div
            style={{
              position: "fixed",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundColor: "rgba(0,0,0,0.5)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              zIndex: 1000,
            }}
          >
            <div
              // ref={viewModalRef}
              style={{
                backgroundColor: "#fff",
                borderRadius: "10px",
                maxWidth: "600px",
                width: "90%",
                maxHeight: "95vh", // modal still limited to viewport height

                boxShadow: "0 0 10px rgba(0,0,0,0.3)",
                position: "relative",
                overflowY: "scroll",
              }}
              className="no-scrollbar"
            >
              <div
                style={{
                  backgroundColor: "#3a3a3a",
                  color: "#fff",
                  padding: "15px 20px",
                  fontSize: "18px",
                  fontWeight: "bold",
                   position:"sticky",
                   top:"0",
                   zIndex: 10,
                }}
              >
                Seller Details
                <button
                  onClick={() => setShowViewModal(false)}
                  style={{
                    position: "absolute",
                    top: "10px",
                    right: "10px",
                    background: "transparent",
                    border: "none",
                    fontSize: "22px",
                    color: "#fff",
                    cursor: "pointer",
                   
                   
                  }}
                >
                  &times;
                </button>
              </div>

              <div
                style={{
                  display: "flex",
                  flexWrap: "wrap",
                  padding: "20px",
                  gap: "20px",
                  color: "#333",
                }}
              >
                {/* Left Column */}
                <div style={{ flex: 1, minWidth: "250px" }}>
                  <div style={{ marginBottom: "15px" }}>
                    <strong>Seller Name</strong>
                    <p>{selectedSeller?.basicInformation?.shopName||"-"}</p>
                  </div>
                  {/* <div style={{ marginBottom: "15px" }}>
                    <strong>Centre Type</strong>
                    <p>{selectedSeller?.basicInformation?.shopType}</p>
                  </div> */}
                 
              
                </div>

                {/* Right Column */}
                <div style={{ flex: 1, minWidth: "250px" }}>
                  <div style={{ marginBottom: "15px" }}>
                    <strong>Email</strong>
                    <p>{selectedSeller?.contactInformation?.emailAddress||"-"}</p>
                  </div>
                  <div style={{ marginBottom: "15px" }}>
                    <strong>Phone</strong>
                    <p>{selectedSeller?.contactInformation?.Mobileprimary||"-"}</p>
                  </div>
 </div>
              </div>
            </div>
          </div>
        )}
        </div>
      </div>
    </div>
  );
};

export default RegisteredSellerLayer;
